import { Icon, type IconifyIcon } from '@iconify/react/offline';
import { Archive, Box, Container, Database, Globe, ListOrdered, Network, Package, Waypoints, Zap, type LucideIcon } from 'lucide-react';
import cloudIcons from '@/lib/cloud-icons.json';
import { cn } from '@/lib/utils';

/*
 * Offline icons only: `@iconify/react/offline` contains no API loader, and the icon bodies come
 * from src/lib/cloud-icons.json (generated by scripts/extract-icons.mjs from @iconify-json/logos).
 */
const ICONS = cloudIcons as Record<string, IconifyIcon>;

export const RESOURCE_TYPE_META: Record<string, { label: string; glyph: LucideIcon; short: string }> = {
  network: { label: 'Network', glyph: Network, short: 'network' },
  'compute.container-service': { label: 'Container service', glyph: Container, short: 'service' },
  'container-registry': { label: 'Container registry', glyph: Package, short: 'registry' },
  'database.postgresql': { label: 'PostgreSQL', glyph: Database, short: 'database' },
  'cache.redis': { label: 'Redis cache', glyph: Zap, short: 'cache' },
  queue: { label: 'Queue', glyph: ListOrdered, short: 'queue' },
  'object-storage': { label: 'Object storage', glyph: Archive, short: 'storage' },
  ingress: { label: 'Ingress', glyph: Waypoints, short: 'ingress' },
  dns: { label: 'DNS', glyph: Globe, short: 'dns' },
};

/** AWS service icons by capability, then by logical type. */
const AWS_BY_CAPABILITY: Record<string, string> = {
  vpc: 'aws-vpc',
  'ecs-fargate': 'aws-fargate',
  'ecs-ec2': 'aws-ecs',
  'ecs-managed-instances': 'aws-ecs',
  'rds-postgres': 'aws-rds',
  'elasticache-valkey': 'aws-elasticache',
  sqs: 'aws-sqs',
  s3: 'aws-s3',
  alb: 'aws-elb',
  route53: 'aws-route53',
};
const AWS_BY_TYPE: Record<string, string> = {
  network: 'aws-vpc',
  'compute.container-service': 'aws-ecs',
  'database.postgresql': 'aws-rds',
  'cache.redis': 'aws-elasticache',
  queue: 'aws-sqs',
  'object-storage': 'aws-s3',
  ingress: 'aws-elb',
  dns: 'aws-route53',
};
/** Providers without per-service icons in the set: provider logo + a resource-kind glyph. */
const PROVIDER_LOGO: Record<string, string> = { aws: 'aws', azure: 'azure-icon', gcp: 'google-cloud', oci: 'oracle' };
/** Provider-neutral technology logos (templates, unknown providers). */
const TECH_BY_TYPE: Record<string, string> = {
  'database.postgresql': 'postgresql',
  'cache.redis': 'redis',
  'compute.container-service': 'docker',
};

export function ProviderLogo({ provider, size = 16, className }: { provider: string; size?: number; className?: string }) {
  const name = PROVIDER_LOGO[provider];
  const data = name ? ICONS[name] : undefined;
  if (!data) return null;
  return <Icon icon={data} width={size} height={size} className={className} aria-hidden />;
}

/**
 * One icon for a resource, keyed by (type, capability, provider/simulatedProvider). Mock
 * resources use the icon of the cloud they simulate.
 */
export function ResourceIcon({
  type,
  capability,
  provider,
  simulatedProvider,
  size = 20,
  className,
}: {
  type: string;
  capability?: string | null;
  provider?: string | null;
  simulatedProvider?: string | null;
  size?: number;
  className?: string;
}) {
  const effective = simulatedProvider ?? (provider === 'mock' ? null : provider) ?? null;
  const meta = RESOURCE_TYPE_META[type];
  const Glyph = meta?.glyph ?? Box;

  if (effective === 'aws') {
    const name = (capability && AWS_BY_CAPABILITY[capability]) || AWS_BY_TYPE[type];
    const data = name ? ICONS[name] : undefined;
    if (data) return <Icon icon={data} width={size} height={size} className={cn('shrink-0', className)} aria-hidden />;
  }

  if (effective && PROVIDER_LOGO[effective]) {
    const badge = Math.round(size * 0.55);
    return (
      <span className={cn('relative inline-flex shrink-0', className)} style={{ width: size, height: size }} aria-hidden>
        <Glyph size={size} strokeWidth={1.6} className="text-fg-muted" />
        <span className="absolute -bottom-1 -right-1 rounded-sm bg-surface p-px ring-1 ring-border">
          <ProviderLogo provider={effective} size={badge} />
        </span>
      </span>
    );
  }

  const tech = TECH_BY_TYPE[type];
  const techData = tech ? ICONS[tech] : undefined;
  if (techData) return <Icon icon={techData} width={size} height={size} className={cn('shrink-0', className)} aria-hidden />;
  return <Glyph size={size} strokeWidth={1.6} className={cn('shrink-0 text-fg-muted', className)} aria-hidden />;
}
